MARK=MARK or{}local a=tonumber;local b=math.clamp;function MARK.settings()local c={type="panel",name=MARK.name,displayName=MARK.addonInfo.title,author=MARK.addonInfo.author,registerForRefresh=true}LibAddonMenu2:RegisterAddonPanel(MARK.name.." - Options",c)local e={{type="checkbox",name="Marker Icon in Chat",tooltip="Enable the Chat Menu Button",getFunc=function()if MARK.savedVars.showChatButton==nil then return true end;return MARK.savedVars.showChatButton end,setFunc=function(f)MARK.savedVars.showChatButton=f;if f then MARK.chatButton:show()else MARK.chatButton:hide()end end},{type="checkbox",name="Show all emotes in selection",tooltip="Show all 1000+ emotes when you select a texture",getFunc=function()return MARK.savedVars.emotePackName~="mark"end,setFunc=function(f)MARK.savedVars.emotePackName=f and""or"mark"end},{type="editbox",name="Icon-Size multiplier (%)",tooltip="Size multiplier for all icons",getFunc=function()return MARK.savedVars.iconsizemultiplier or 100 end,setFunc=function(g)MARK.savedVars.iconsizemultiplier=b(a(g)or 100,10,1000)MARK.ClearAndReload()end,isMultiline=false,default=100,textType=TEXT_TYPE_NUMERIC,maxChars=3},{type="editbox",name="Distance",tooltip="Radius of the distance check (in cm)",getFunc=function()return MARK.savedVars.radius end,setFunc=function(g)MARK.savedVars.radius=b(a(g)or 10000,500,100000)MARK.reloadProfile()end,isMultiline=false,default=10000,textType=TEXT_TYPE_NUMERIC,maxChars=5},{type="editbox",name="Delay",tooltip="Amount of milliseconds before all markers are updated again (min 100, max 10000)",getFunc=function()return MARK.savedVars.delay end,setFunc=function(g)MARK.savedVars.delay=b(a(g)or 2000,100,10000)MARK.reloadProfile()end,isMultiline=false,default=2000,textType=TEXT_TYPE_NUMERIC,maxChars=5},{type="editbox",name="Minimum delay",tooltip="Minimal delay between each marker update (min 5, max 1000)",getFunc=function()return MARK.savedVars.minimumdelay end,setFunc=function(g)MARK.savedVars.minimumdelay=b(a(g)or 50,5,10